"use client";

import { Checkbox, Stack } from '@mantine/core';

function Demo() {
  return (
    <Checkbox.Group
      disabled
      label="Select your favorite frameworks/libraries"
      description="This is anonymous"
    >
      <Stack mt="xs">
        <Checkbox value="react" label="React" />
        <Checkbox value="svelte" label="Svelte" />
        <Checkbox value="angular" label="Angular" />
        <Checkbox value="vue" label="Vue" />
      </Stack>
    </Checkbox.Group>
  );
}
const RendynExampleComponent = Demo;
export function RendynExample() { return <RendynExampleComponent  />; }

"use client";

import { RendynExample as Example } from "@/components/rendyn-libraries/mantine/upstream/src/demos/core/Checkbox/CheckboxGroup.demo.disabled";
import { MantineProvider } from "@mantine/core";
import "@mantine/core/styles.css";

export default function Preview() {

  return <div style={{ width: "100%", maxWidth: "48rem", padding: "1.5rem" }}><MantineProvider><Example /></MantineProvider></div>;
}
